def topological_sort(graph: dict[str, list[str]]) -> tuple[list[str], list[str] | None]:
    """Return topological order or cycle nodes."""
    visited, on_stack, stack, order = set(), set(), [], []
    cycle = []  # will hold list of nodes forming a cycle

    def dfs(u):
        nonlocal cycle
        visited.add(u)
        on_stack.add(u)
        stack.append(u)
        for v in graph.get(u, []):
            if v not in visited:
                if dfs(v):
                    return True
            elif v in on_stack:
                idx = stack.index(v)
                cycle = stack[idx:]  # nodes from v to u forming the cycle
                return True
        on_stack.remove(u)
        stack.pop()
        order.append(u)
        return False

    # include nodes that appear only as dependencies
    all_nodes = set(graph) | {n for lst in graph.values() for n in lst}
    for n in all_nodes:
        if n not in visited:
            if dfs(n):
                break

    if cycle:
        return ([], cycle)
    return (order[::-1], None)
